<template><Head><title>{{ recipe ? 'Рецептура v' + recipe.version : 'Новая рецептура' }}</title></Head><div class="mi-page"><div class="content-header"><div class="container-fluid"><h5 class="m-0">{{ recipe ? 'Рецептура v' + recipe.version : 'Новая рецептура' }}</h5></div></div><div class="content"><div class="container-fluid"><div class="card card-primary"><form @submit.prevent="submit"><div class="card-body"><div class="mx-auto col-md-8"><div class="form-group"><label>Продукция</label><select v-model.number="form.nomenclature_id" class="form-control" :disabled="!!recipe"><option :value="null">Выберите продукцию</option><option v-for="product in products" :value="product.id">{{ product.name }}</option></select></div><div class="form-group"><label><input v-model="form.is_active" type="checkbox"> Активная версия</label></div><div class="table-responsive mi-table-wrap"><table class="table table-bordered mi-mobile-table mi-form-table"><thead><tr><th>Материал</th><th>Расход на единицу</th><th></th></tr></thead><tbody><tr v-for="(item, index) in form.items"><td data-label="Материал"><select v-model.number="item.material_nomenclature_id" class="form-control"><option :value="null">Материал</option><option v-for="material in materials" :value="material.id">{{ material.name }} ({{ material.unit }})</option></select></td><td data-label="Расход на единицу"><input v-model="item.quantity_per_unit" type="number" step="0.000001" min="0" class="form-control"></td><td data-label=""><button type="button" class="btn btn-outline-danger" @click="form.items.splice(index, 1)">Удалить</button></td></tr></tbody></table></div><button type="button" class="btn btn-outline-secondary" @click="addItem">Добавить материал</button><div v-if="errors.items" class="text-danger mt-2">{{ errors.items }}</div></div></div><div class="card-footer mi-actions"><button v-if="!recipe || !recipe.is_used" class="btn btn-primary" :disabled="form.processing">Сохранить</button><button v-if="recipe && recipe.is_used" type="button" class="btn btn-primary" @click="newVersion">Создать новую версию</button><button v-if="recipe && !recipe.is_active" type="button" class="btn btn-success" @click="activate">Активировать</button><Link :href="route('production-recipes.index')" class="btn btn-default">К списку</Link></div></form></div></div></div></div></template>
<script>import {Head, Link, useForm} from '@inertiajs/inertia-vue3'; export default {components: {Head, Link}, props: ['recipe', 'products', 'materials', 'errors'], data() { return {form: useForm({nomenclature_id: this.recipe?.nomenclature_id || null, is_active: this.recipe?.is_active || false, items: (this.recipe?.items || []).map(item => ({material_nomenclature_id: item.material_nomenclature_id, quantity_per_unit: item.quantity_per_unit}))})} }, methods: {addItem() { this.form.items.push({material_nomenclature_id: null, quantity_per_unit: null}) }, submit() { this.recipe ? this.form.put(route('production-recipes.update', this.recipe.id)) : this.form.post(route('production-recipes.store')) }, activate() { this.$inertia.post(route('production-recipes.activate', this.recipe.id)) }, newVersion() { this.$inertia.post(route('production-recipes.versions.store', this.recipe.id)) }}};</script>
